const D = { energy: .6, scale: 1, speed: 1, density: .5, spines: .6, hue: 34, x: .5, y: .5, style: 'darkfield', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// A plankton tow under the objective: foraminifera and radiolaria, the mineral
// skeletons of single-celled protists. Two builds appear. RADIOLARIA are latticed
// silica spheres nested one inside another, their surface a geodesic net pierced
// by pores at every node, from which long radial aximo-spines (axopodia) fan out --
// the classic Haeckel star. FORAMINIFERA are calcite trochospirals: a run of
// swelling chambers wound on a log spiral, each domed and stippled with pores,
// trailing short calcite spines. Every test drifts on a bounded orbit, turns on
// two incommensurate rates, and slowly breathes its spines in and out so nothing
// ever converges; an oblique illumination lights the near flank of each shell,
// breaking the radial symmetry frame to frame.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sp = 0.25 + P.speed * 0.9;
const spineAmt = 0.15 + P.spines * 1.0;

const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7 + 1.3) * 43758.5453; return s - Math.floor(s); };

const nSpec = Math.round(3 + P.density * 8);
if (!S.spec || S.seedUsed !== P.seed || S.nUsed !== nSpec) {
  S.seedUsed = P.seed; S.nUsed = nSpec;
  S.spec = [];
  for (let k = 0; k < nSpec; k++) {
    const radiolarian = fr(k * 3 + 1) < 0.58;
    S.spec.push({
      radiolarian,
      bx: 0.12 + fr(k * 7 + 3) * 0.76,
      by: 0.14 + fr(k * 7 + 4) * 0.72,
      rad: 0.055 + fr(k * 11 + 5) * 0.11,
      shells: 1 + Math.floor(fr(k * 13 + 6) * 2.8),        // nested shells (radiolaria)
      merid: 8 + Math.floor(fr(k * 17 + 7) * 12),          // meridians / lattice longitudes
      lats: 3 + Math.floor(fr(k * 19 + 8) * 3),            // lattice latitudes
      nSpine: 10 + Math.floor(fr(k * 23 + 9) * 14),
      chambers: 4 + Math.floor(fr(k * 29 + 10) * 4),       // foram chamber count
      chamGrow: 1.14 + fr(k * 31 + 11) * 0.18,             // chamber size ratio
      rot0: fr(k * 37 + 12) * 6.2831853,
      rr1: 0.016 + fr(k * 41 + 13) * 0.045,
      rr2: 0.010 + fr(k * 43 + 14) * 0.03,
      dph1: fr(k * 47 + 15) * 6.283, dph2: fr(k * 53 + 16) * 6.283,
      dr1: 0.045 + fr(k * 59 + 17) * 0.08, dr2: 0.038 + fr(k * 61 + 18) * 0.075,
      damp: 0.01 + fr(k * 67 + 19) * 0.028,
      bph: fr(k * 71 + 20) * 6.283,                         // spine-breath phase
      hueOff: (fr(k * 73 + 21) - 0.5) * 40
    });
  }
}

const t = K.t;
const style = P.style;
const glow = 0.4 + P.energy * 1.2 + A.rms * 0.35;
const lightAng = t * 0.1 * sp + 0.5 * Math.sin(t * 0.041) + 0.25 * Math.sin(t * 0.097 + 0.8);
const breath = 0.9 + 0.1 * Math.sin(t * 0.31 * sp) + A.lowmid * 0.15;

let bgH, bgS, bgB, mode;
if (style === 'plate') { bgH = 34; bgS = 22; bgB = 66; mode = 'plate'; }
else if (style === 'blueprint') { bgH = 214; bgS = 62; bgB = 26; mode = 'blueprint'; }
else if (style === 'fluor') { bgH = 232; bgS = 55; bgB = 9; mode = 'fluor'; }
else { bgH = 200; bgS = 48; bgB = 11; mode = 'darkfield'; }
const pale = (mode === 'plate');

push();
noStroke(); rectMode(CORNER);
fill(bgH, bgS, bgB); rect(0, 0, width, height);
// condenser illumination pool
for (let ri = 6; ri >= 1; ri--) {
  const rr = u * (0.3 + ri * 0.13);
  if (mode === 'plate') fill(bgH, bgS * 0.6, bgB + (7 - ri) * 2.8 * (0.7 + glow * 0.4), 26);
  else if (mode === 'blueprint') fill(bgH, bgS, Math.min(48, bgB + (7 - ri) * 2.4), 20);
  else fill(bgH, bgS * 0.5, Math.min(80, bgB + (7 - ri) * 3.0), 22);
  ellipse(P.x * width * 0.35 + width * 0.325, P.y * height * 0.35 + height * 0.325, rr * 2.2, rr * 2.0);
}

// helper: line/stroke colour respecting style + oblique light
function litStroke(baseB, ang, hue, sat, a) {
  const lit = 0.4 + 0.6 * Math.max(0, Math.cos(ang - lightAng));
  if (pale) stroke((hue + 20) % 360, sat + 16, 18 + (1 - lit) * 14, a);
  else stroke(hue, sat, Math.min(100, baseB * (0.32 + lit) * (0.75 + glow * 0.5)), a);
}

if (mode === 'fluor') blendMode(ADD);

for (let si = 0; si < S.spec.length; si++) {
  const m = S.spec[si];
  const px = (m.bx + m.damp * Math.sin(t * m.dr1 * sp + m.dph1)) * width;
  const py = (m.by + m.damp * Math.cos(t * m.dr2 * sp + m.dph2)) * height;
  const rot = m.rot0 + m.rr1 * t * sp + 0.3 * Math.sin(m.rr2 * t * sp + m.dph1);
  const R = m.rad * u * P.scale * breath;
  if (R < 3) continue;
  const hue = (P.hue + m.hueOff + 360) % 360;
  const sat = mode === 'blueprint' ? 30 : (mode === 'fluor' ? 66 : 40);

  push(); translate(px, py); rotate(rot); noFill();

  if (m.radiolarian) {
    // long radial aximo-spines first (behind shell)
    const nsp = m.nSpine, sl = R * (1 + spineAmt * (1.0 + 0.25 * Math.sin(t * 0.5 * sp + m.bph)));
    for (let a = 0; a < nsp; a++) {
      const th = a / nsp * 6.2831853;
      strokeWeight(Math.max(0.4, R * 0.02 * (1 - a / nsp * 0.3)));
      litStroke(66, th + rot, hue, sat, 66);
      line(Math.cos(th) * R * 0.6, Math.sin(th) * R * 0.6, Math.cos(th) * sl, Math.sin(th) * sl);
    }
    // nested lattice shells
    for (let s2 = 0; s2 < m.shells; s2++) {
      const rr = R * (1 - s2 * 0.34);
      if (rr < 4) break;
      // shell fill halo
      if (!pale) { noStroke(); fill(hue, mode === 'fluor' ? 72 : 46, mode === 'fluor' ? 34 : 20, 20 + glow * 8); ellipse(0, 0, rr * 2, rr * 2); noFill(); }
      strokeWeight(Math.max(0.6, R * 0.014));
      litStroke(72, lightAng, hue, sat, 82);
      ellipse(0, 0, rr * 2, rr * 2);
      // geodesic net: meridians + latitudes
      strokeWeight(Math.max(0.4, R * 0.007));
      for (let mm = 0; mm < m.merid; mm++) {
        const ph = mm / m.merid * Math.PI;
        litStroke(58, ph + rot, hue, sat, 54);
        // projected meridian as an ellipse squashed by cos(phase)
        const w2 = rr * Math.abs(Math.cos(ph)) * 2, h2 = rr * 2;
        push(); rotate(ph); ellipse(0, 0, Math.max(2, w2), h2); pop();
      }
      for (let lt = 1; lt < m.lats; lt++) {
        const rl = rr * lt / m.lats;
        litStroke(52, lightAng, hue, sat, 50);
        ellipse(0, 0, rl * 2, rl * 2);
      }
      // pores at nodes (only on outer shell, when large enough)
      if (s2 === 0 && R > u * 0.055) {
        strokeWeight(Math.max(0.7, R * 0.02));
        for (let mm = 0; mm < m.merid; mm++) for (let lt = 1; lt < m.lats; lt++) {
          const th = mm / m.merid * 6.2831853, rl = rr * lt / m.lats;
          litStroke(64, th + rot, hue, sat, 60);
          point(Math.cos(th) * rl, Math.sin(th) * rl);
        }
      }
    }
    // central capsule + lit highlight crescent
    strokeWeight(Math.max(0.6, R * 0.014)); litStroke(80, lightAng, hue, sat, 88);
    ellipse(0, 0, R * 0.3, R * 0.3);
    if (!pale) { noStroke(); fill((hue + 10) % 360, sat * 0.6, Math.min(100, 70 * glow), 30);
      const lc = lightAng - rot; ellipse(Math.cos(lc) * R * 0.5, Math.sin(lc) * R * 0.5, R * 0.5, R * 0.5); noFill(); }
  } else {
    // foraminifera trochospiral: swelling chambers on a log spiral
    let rr = R * 0.34, ang = 0, cxp = 0, cyp = 0;
    for (let c = 0; c < m.chambers; c++) {
      ang += 2.399963 * (0.7 + 0.3 * (c / m.chambers));   // ~golden-angle winding, opening out
      const step = rr * 1.15;
      cxp += Math.cos(ang) * step * 0.5; cyp += Math.sin(ang) * step * 0.5;
      // chamber dome
      if (!pale) { noStroke(); fill(hue, mode === 'fluor' ? 70 : 44, mode === 'fluor' ? 36 : 22, 34 + glow * 10); ellipse(cxp, cyp, rr * 2, rr * 2); noFill(); }
      strokeWeight(Math.max(0.6, R * 0.016)); litStroke(74, Math.atan2(cyp, cxp), hue, sat, 84);
      ellipse(cxp, cyp, rr * 2, rr * 2);
      // pore stipple + lit crescent
      if (R > u * 0.05) { strokeWeight(Math.max(0.7, R * 0.02));
        const npo = 7 + (fr(c + si * 9) * 6 | 0);
        for (let pj = 0; pj < npo; pj++) { const pa = fr(pj + c * 3 + si) * 6.283, pd = fr(pj * 2 + c) * rr * 0.8; litStroke(60, pa, hue, sat, 55); point(cxp + Math.cos(pa) * pd, cyp + Math.sin(pa) * pd); } }
      if (!pale) { noStroke(); const lc = lightAng - rot; fill((hue + 8) % 360, sat * 0.6, Math.min(100, 66 * glow), 26); ellipse(cxp + Math.cos(lc) * rr * 0.4, cyp + Math.sin(lc) * rr * 0.4, rr * 0.7, rr * 0.7); noFill(); }
      // short spines on the final (aperture) chambers
      if (c >= m.chambers - 2) { const ns = 9; for (let a = 0; a < ns; a++) { const th = a / ns * 6.2831853; strokeWeight(Math.max(0.4, R * 0.01)); litStroke(58, th + rot, hue, sat, 50); line(cxp + Math.cos(th) * rr, cyp + Math.sin(th) * rr, cxp + Math.cos(th) * rr * (1 + spineAmt * 0.5), cyp + Math.sin(th) * rr * (1 + spineAmt * 0.5)); } }
      rr *= m.chamGrow;
    }
  }
  pop();
}
if (mode === 'fluor') blendMode(BLEND);

// faint vignette
noFill();
for (let vi = 0; vi < 5; vi++) { stroke(bgH, bgS, pale ? 0 : (mode === 'blueprint' ? 12 : 40), 8); strokeWeight(u * (0.05 + vi * 0.02)); ellipse(width / 2, height / 2, width * (1.02 + vi * 0.03), height * (1.02 + vi * 0.03)); }
pop();

if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(bgH, bgS, bgB, 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
